import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';

/** Total processing attempts a job gets before it is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Duration of one processing step. */
export const STEP_MS = 100;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_STALE_MS = 3_000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A validated submission, with defaults already applied. */
export interface JobSubmission {
  input: string;
  steps: number;
  failAttempts: number;
}

/** The public job shape returned by every endpoint. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** A row of the `jobs` table. */
interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  output: string | null;
  error: string | null;
  idempotency_key: string | null;
  fingerprint: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** What the worker needs to run one attempt. */
export interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
}

function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' && row.output !== null ? { output: row.output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function now(): string {
  return new Date().toISOString();
}

function findRow(db: DatabaseSync, column: 'id' | 'idempotency_key', value: string): JobRow | undefined {
  return db.prepare(`SELECT * FROM jobs WHERE ${column} = ?`).get(value) as unknown as JobRow | undefined;
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = findRow(db, 'id', id);
  return row && toJob(row);
}

export function listJobs(db: DatabaseSync): Job[] {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  return rows.map(toJob);
}

export type SubmitOutcome = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/**
 * Creates a job, or, when an idempotency key is given, returns the job created earlier with that
 * key (if the payload matches) or reports a conflict. The lookup and insert run in one immediate
 * transaction, so a key can never create two jobs, even across processes.
 */
export function submitJob(db: DatabaseSync, submission: JobSubmission, key: string | undefined): SubmitOutcome {
  const fingerprint = JSON.stringify([submission.input, submission.steps, submission.failAttempts]);
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== undefined) {
      const existing = findRow(db, 'idempotency_key', key);
      if (existing) {
        db.exec('COMMIT');
        return existing.fingerprint === fingerprint
          ? { kind: 'replayed', job: toJob(existing) }
          : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const ts = now();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed,
                         idempotency_key, fingerprint, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
    ).run(id, submission.input, submission.steps, submission.failAttempts, key ?? null, key === undefined ? null : fingerprint, ts, ts);
    const row = findRow(db, 'id', id)!;
    db.exec('COMMIT');
    return { kind: 'created', job: toJob(row) };
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

/**
 * Moves the oldest queued job that is due to `running`, increments its attempt counter and resets
 * its progress. Returns undefined when nothing is due.
 */
export function claimNextJob(db: DatabaseSync): ClaimedJob | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`)
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) {
      db.exec('COMMIT');
      return undefined;
    }
    db.prepare(`UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ?`).run(now(), row.id);
    db.exec('COMMIT');
    return { id: row.id, input: row.input, steps: row.steps, failAttempts: row.fail_attempts, attempts: row.attempts + 1 };
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

export function setProgress(db: DatabaseSync, id: string, completed: number): void {
  db.prepare(`UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(completed, now(), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', output = ?, completed = steps, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(output, now(), id);
}

export function failJob(db: DatabaseSync, id: string, error: string): void {
  db.prepare(`UPDATE jobs SET status = 'failed', error = ?, output = NULL, completed = 0, updated_at = ? WHERE id = ? AND status = 'running'`).run(
    error,
    now(),
    id,
  );
}

/** Returns a running job to the queue, to be picked up again once `runAfter` (epoch ms) has passed. */
export function requeueJob(db: DatabaseSync, id: string, runAfter: number): void {
  db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(
    runAfter,
    now(),
    id,
  );
}

/**
 * Called once at worker startup. Jobs still marked `running` belong to a worker that died mid-attempt.
 * They go back to the queue and are processed again. The interrupted attempt is not counted against the
 * final attempt, so a crash during attempt 3 re-runs attempt 3 instead of exceeding the limit.
 */
export function recoverInterruptedJobs(db: DatabaseSync): number {
  const result = db
    .prepare(
      `UPDATE jobs
          SET status = 'queued',
              attempts = CASE WHEN attempts >= ? THEN attempts - 1 ELSE attempts END,
              completed = 0,
              run_after = 0,
              updated_at = ?
        WHERE status = 'running'`,
    )
    .run(MAX_ATTEMPTS, now());
  return Number(result.changes);
}

export function writeHeartbeat(db: DatabaseSync): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (id, seen_at) VALUES (1, ?)
     ON CONFLICT (id) DO UPDATE SET seen_at = excluded.seen_at`,
  ).run(Date.now());
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat').run();
}

export function isWorkerUp(db: DatabaseSync, nowMs: number): boolean {
  const row = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id = 1').get() as { seen_at: number } | undefined;
  return row !== undefined && nowMs - row.seen_at <= HEARTBEAT_STALE_MS;
}

