import type { JobSubmission } from './jobs.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type ValidationResult = { ok: true; value: JobSubmission } | { ok: false; errors: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const MAX_INPUT_LENGTH = 1000;

export function validateIdempotencyKey(key: string): FieldError | undefined {
  return IDEMPOTENCY_KEY_PATTERN.test(key)
    ? undefined
    : { field: 'Idempotency-Key', message: 'must be 1 to 128 characters: letters, digits, "_" or "-"' };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Validates a parsed request body. Every offending field is reported, not just the first. */
export function validateSubmission(body: unknown): ValidationResult {
  if (!isRecord(body)) return { ok: false, errors: [{ field: 'body', message: 'must be a JSON object' }] };

  const errors: FieldError[] = [];
  for (const name of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(name)) errors.push({ field: name, message: 'unknown field' });
  }
  const get = (name: string): unknown => (Object.hasOwn(body, name) ? body[name] : undefined);

  let input = '';
  const rawInput = get('input');
  if (rawInput === undefined) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof rawInput !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (rawInput.length < 1 || rawInput.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (rawInput.trim() === '') {
    errors.push({ field: 'input', message: 'must not be blank' });
  } else {
    input = rawInput;
  }

  const steps = integerField(get, 'steps', 1, 20, 5, errors);
  const failAttempts = integerField(get, 'failAttempts', 0, 5, 0, errors);

  if (errors.length > 0) return { ok: false, errors };
  return { ok: true, value: { input, steps, failAttempts } };
}

function integerField(
  get: (name: string) => unknown,
  name: string,
  min: number,
  max: number,
  fallback: number,
  errors: FieldError[],
): number {
  const raw = get(name);
  if (raw === undefined) return fallback;
  if (typeof raw !== 'number' || !Number.isInteger(raw)) {
    errors.push({ field: name, message: 'must be an integer' });
  } else if (raw < min || raw > max) {
    errors.push({ field: name, message: `must be between ${min} and ${max}` });
  } else {
    return raw;
  }
  return fallback;
}

