import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  clearHeartbeat,
  claimNextJob,
  completeJob,
  failJob,
  MAX_ATTEMPTS,
  recoverInterruptedJobs,
  requeueJob,
  setProgress,
  STEP_MS,
  writeHeartbeat,
  type ClaimedJob,
} from './jobs.ts';
import type { DatabaseSync } from 'node:sqlite';

const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
const RETRY_MIN_MS = 250;
const RETRY_MAX_MS = 2_000;

const db = openDatabase();
const recovered = recoverInterruptedJobs(db);
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);
writeHeartbeat(db);
const heartbeat = setInterval(() => writeHeartbeat(db), HEARTBEAT_MS);

let stopping = false;
function shutdown(): void {
  if (stopping) return;
  stopping = true;
  clearInterval(heartbeat);
  // Any job still `running` is recovered by the next worker start. Every write is synchronous and
  // committed, so exiting here cannot leave a partial write behind.
  try {
    clearHeartbeat(db);
    db.close();
  } finally {
    process.exit(0);
  }
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

/** Runs one attempt of a claimed job, either failing it transiently or processing every step. */
async function runAttempt(db: DatabaseSync, job: ClaimedJob): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    await sleep(STEP_MS); // the first step fails before any progress is made
    if (job.attempts < MAX_ATTEMPTS) {
      const delay = RETRY_MIN_MS + Math.floor(Math.random() * (RETRY_MAX_MS - RETRY_MIN_MS + 1));
      requeueJob(db, job.id, Date.now() + delay);
    } else {
      failJob(db, job.id, 'transient failure');
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    setProgress(db, job.id, step);
  }
  completeJob(db, job.id, job.input.toUpperCase());
}

console.log('worker started');
while (!stopping) {
  const job = claimNextJob(db);
  if (!job) {
    await sleep(IDLE_POLL_MS);
    continue;
  }
  await runAttempt(db, job);
}

