import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import type { DatabaseSync } from 'node:sqlite';
import { openDatabase } from './db.ts';
import { getJob, isWorkerUp, listJobs, submitJob, type Job, type JobSubmission } from './jobs.ts';
import { validateIdempotencyKey, validateSubmission, type FieldError } from './validation.ts';

const MAX_BODY_BYTES = 16 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  sendJson(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allow}.`);
}

/** Returns a header as one string. Repeated headers are joined, which fails any strict format check. */
function headerValue(req: IncomingMessage, name: string): string | undefined {
  const value = req.headers[name];
  return Array.isArray(value) ? value.join(', ') : value;
}

function isJsonContentType(value: string | undefined): boolean {
  if (value === undefined) return false;
  return (value.split(';', 1)[0] ?? '').trim().toLowerCase() === 'application/json';
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function handleCreate(db: DatabaseSync, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];
  const keyHeader = headerValue(req, 'idempotency-key');
  if (keyHeader !== undefined) {
    const keyError = validateIdempotencyKey(keyHeader);
    if (keyError) errors.push(keyError);
  }

  const { text, tooLarge } = await readBody(req);
  let submission: JobSubmission | undefined;
  if (!isJsonContentType(headerValue(req, 'content-type'))) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    errors.push({ field: 'body', message: `must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let parsedOk = false;
    try {
      parsed = JSON.parse(text);
      parsedOk = true;
    } catch {
      errors.push({ field: 'body', message: 'is not valid JSON' });
    }
    if (parsedOk) {
      const result = validateSubmission(parsed);
      if (result.ok) submission = result.value;
      else errors.push(...result.errors);
    }
  }

  if (errors.length > 0 || submission === undefined) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', errors);
    return;
  }

  const outcome = submitJob(db, submission, keyHeader);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    return sendJson(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return sendJson(res, 200, { jobs: listJobs(db) satisfies Job[] });
    if (method === 'POST') return handleCreate(db, req, res);
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    const job = getJob(db, decodeURIComponent(match[1]!));
    if (!job) return sendError(res, 404, 'not_found', 'No job with that id.');
    return sendJson(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close();
  server.closeAllConnections();
  db.close();
  process.exit(0);
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

