import { spawn } from 'node:child_process';
const ROOT = process.env.ROOT;
const DB = process.env.TMPDIR + '/jt/data/jobs.db';
const PORT = 3917;
const base = `http://127.0.0.1:${PORT}`;
const env = { ...process.env, PORT: String(PORT), DATABASE_PATH: DB };
const procs = {};
const start = (name) => { procs[name] = spawn('node', ['--disable-warning=ExperimentalWarning', `${ROOT}/dist/${name}.js`], { env, stdio: ['ignore', 'inherit', 'inherit'] }); };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
let fails = 0;
const check = (cond, msg) => { console.log((cond ? 'PASS ' : 'FAIL ') + msg); if (!cond) fails++; };
async function call(method, path, body, headers = {}) {
  const r = await fetch(base + path, { method, headers: body === undefined ? headers : { 'content-type': 'application/json', ...headers }, body: body === undefined ? undefined : (typeof body === 'string' ? body : JSON.stringify(body)) });
  const text = await r.text(); let json; try { json = JSON.parse(text); } catch {}
  return { status: r.status, ct: r.headers.get('content-type'), json, text };
}
async function waitFor(id, pred, ms = 15000) {
  const end = Date.now() + ms;
  while (Date.now() < end) { const j = (await call('GET', `/api/jobs/${id}`)).json; if (pred(j)) return j; await sleep(100); }
  return (await call('GET', `/api/jobs/${id}`)).json;
}
const { rmSync } = await import('node:fs');
rmSync(process.env.TMPDIR + '/jt/data', { recursive: true, force: true });
start('server'); start('worker');
await sleep(1500);
let h = await call('GET', '/health');
check(h.status === 200 && h.json.status === 'ok' && h.json.worker === 'up', 'health ok + worker up: ' + h.text);

// validation
const bad = [
  [{ input: 'a', steps: '3' }, 'steps'],
  [{ input: 'a', failAttempts: 6 }, 'failAttempts'],
  [{ input: 'a', steps: 2.5 }, 'steps'],
  [{ input: 'a', steps: 21 }, 'steps'],
  [{ input: 'a', colour: 'x' }, 'colour'],
  [{ steps: 2 }, 'input'],
  [{ input: '   ' }, 'input'],
  [{ input: 'x'.repeat(1001) }, 'input'],
  [[1, 2], 'body'],
  [null, 'body'],
];
for (const [b, f] of bad) {
  const r = await call('POST', '/api/jobs', b);
  check(r.status === 400 && r.json.error.code === 'invalid_request' && r.json.error.fields.some((x) => x.field === f), `invalid ${JSON.stringify(b).slice(0, 60)} -> ${f}: ${r.status} ${r.text.slice(0, 150)}`);
}
let r = await call('POST', '/api/jobs', '{bad json', { 'content-type': 'application/json' });
check(r.status === 400 && r.json.error.fields[0].field === 'body', 'malformed json: ' + r.text);
r = await call('POST', '/api/jobs', '{"input":"a"}', { 'content-type': 'text/plain' });
check(r.status === 400 && r.json.error.fields[0].field === 'body', 'text/plain: ' + r.text);
r = await call('POST', '/api/jobs', { input: 'a' }, { 'idempotency-key': 'bad key!' });
check(r.status === 400 && r.json.error.fields.some((x) => x.field === 'Idempotency-Key'), 'bad idem key: ' + r.text);
check((await call('GET', '/api/jobs')).json.jobs.length === 0 || true, 'list ok');

// create + complete
r = await call('POST', '/api/jobs', { input: 'hello ß', steps: 3 });
check(r.status === 201 && r.json.status === 'queued' && r.json.steps === 3 && r.json.failAttempts === 0 && r.json.progress.total === 3, 'create: ' + r.text);
const j1 = await waitFor(r.json.id, (j) => j.status === 'completed');
check(j1.status === 'completed' && j1.result.output === 'HELLO SS' && j1.attempts === 1 && j1.progress.completed === 3 && j1.error === null, 'complete: ' + JSON.stringify(j1));
// defaults
r = await call('POST', '/api/jobs', { input: 'def' });
check(r.json.steps === 5 && r.json.failAttempts === 0, 'defaults: ' + r.text);
const jd = await waitFor(r.json.id, (j) => j.status === 'completed');
check(jd.progress.completed === 5, 'default steps complete');

// retry: failAttempts 2 -> completes on attempt 3
r = await call('POST', '/api/jobs', { input: 'retry2', steps: 2, failAttempts: 2 });
const jr = await waitFor(r.json.id, (j) => j.status === 'completed' || j.status === 'failed', 15000);
check(jr.status === 'completed' && jr.attempts === 3 && jr.result.output === 'RETRY2', 'retry2: ' + JSON.stringify(jr));
// failed: failAttempts 3
r = await call('POST', '/api/jobs', { input: 'doomed', steps: 2, failAttempts: 5 });
const jf = await waitFor(r.json.id, (j) => j.status === 'completed' || j.status === 'failed', 15000);
check(jf.status === 'failed' && jf.error === 'transient failure' && jf.result === null && jf.attempts === 3 && jf.progress.completed === 0, 'failed: ' + JSON.stringify(jf));

// idempotency
const key = { 'idempotency-key': 'k-1' };
const a = await call('POST', '/api/jobs', { input: 'idem', steps: 5, failAttempts: 0 }, key);
const b = await call('POST', '/api/jobs', { input: 'idem' }, key);
check(a.status === 201 && b.status === 200 && a.json.id === b.json.id, `idem replay: ${a.status} ${b.status}`);
const c = await call('POST', '/api/jobs', { input: 'idem2' }, key);
check(c.status === 409 && c.json.error.code === 'idempotency_conflict', 'idem conflict: ' + c.text);
const list = (await call('GET', '/api/jobs')).json.jobs;
check(list.filter((j) => j.input === 'idem' || j.input === 'idem2').length === 1, 'no duplicate idem jobs');
check(list[0].createdAt >= list[1].createdAt, 'newest first');

// routing
check((await call('GET', '/nope')).json.error.code === 'not_found', 'unknown path 404');
r = await call('DELETE', '/api/jobs');
check(r.status === 405 && r.json.error.code === 'method_not_allowed', 'method 405: ' + r.text);
r = await call('POST', '/api/jobs/abc');
check(r.status === 405, 'POST /api/jobs/abc 405');
r = await call('GET', '/api/jobs/%zz');
check(r.status === 404 && r.json.error.code === 'not_found', '%zz 404: ' + r.text);

// restart durability: SIGKILL worker mid-job, and server
r = await call('POST', '/api/jobs', { input: 'kill me', steps: 20 });
const kid = r.json.id;
await waitFor(kid, (j) => j.progress.completed >= 3);
procs.worker.kill('SIGKILL'); procs.server.kill('SIGKILL');
await sleep(500);
const mid = await call('GET', '/api/jobs'); // server is down, check db directly later
start('server'); await sleep(800); start('worker');
const kj = await waitFor(kid, (j) => j.status === 'completed' || j.status === 'failed', 15000);
check(kj.status === 'completed' && kj.result.output === 'KILL ME' && kj.attempts === 2, 'recovered after SIGKILL: ' + JSON.stringify(kj));
const done = (await call('GET', `/api/jobs/${j1.id}`)).json;
check(done.status === 'completed' && done.attempts === 1, 'completed job not reprocessed');

// graceful stop -> health reports worker down
procs.worker.kill('SIGTERM');
await sleep(300);
h = await call('GET', '/health');
check(h.json.worker === 'down', 'worker down after SIGTERM: ' + h.text);
const exitCode = await new Promise((res) => { procs.worker.on('exit', (c, s) => res([c, s])); if (procs.worker.exitCode !== null) res([procs.worker.exitCode]); });
check(exitCode[0] === 0 || exitCode[1] === 'SIGTERM', 'worker exited cleanly ' + exitCode);
procs.server.kill('SIGTERM');
await sleep(300);
check(procs.server.exitCode === 0 || procs.server.signalCode === 'SIGTERM', 'server exited on SIGTERM');
console.log(fails === 0 ? 'ALL PASSED' : `${fails} FAILED`);
process.exit(fails ? 1 : 0);
EOF
